blocks.content:
db.orders.aggregate([
  {
    $lookup: {
      from: "users",
      localField: "userId",
      foreignField: "_id",
      as: "user"
    }
  },
  { $unwind: "$user" },
  {
    $match: {
      "user.city": "Mumbai",
      total: { $gt: 5000 }
    }
  },
  {
    $project: {
      name: "$user.name",
      city: "$user.city",
      product: 1,
      total: 1
    }
  },
  { $sort: { total: -1 } }
]);

